:root {
  color-scheme: dark;
  --bg: #080d0f;
  --bg-2: #0c1417;
  --panel: rgba(17, 27, 31, 0.82);
  --panel-strong: #111b1f;
  --panel-soft: #152226;
  --line: rgba(201, 214, 207, 0.13);
  --line-strong: rgba(201, 214, 207, 0.22);
  --text: #edf5f0;
  --muted: #92a39d;
  --faint: #61716b;
  --teal: #52d6c4;
  --teal-2: #159f92;
  --gold: #e1b866;
  --red: #ff8177;
  --blue: #86aef6;
  --green: #70e0b2;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.42);
  --shadow-tight: 0 16px 44px rgba(0, 0, 0, 0.34);
  --radius: 8px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  overflow-x: hidden;
  color: var(--text);
  background:
    radial-gradient(circle at 30% -20%, rgba(82, 214, 196, 0.12), transparent 28%),
    linear-gradient(135deg, #080d0f 0%, #0d1519 46%, #10100d 100%);
  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
}

button,
input,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

.app {
  min-height: 100vh;
  display: block;
  width: 100%;
  max-width: 100vw;
  overflow-x: hidden;
}

.public-site {
  min-height: 100vh;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.018), transparent 220px),
    radial-gradient(circle at 78% 16%, rgba(225, 184, 102, 0.11), transparent 22%),
    radial-gradient(circle at 8% 34%, rgba(134, 174, 246, 0.08), transparent 24%);
}

.public-nav {
  min-height: 76px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 18px clamp(20px, 5vw, 64px);
  border-bottom: 1px solid var(--line);
  background: rgba(8, 13, 15, 0.86);
  backdrop-filter: blur(22px);
}

.public-nav-actions,
.public-hero-actions,
.portal-tabs {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.public-hero {
  min-height: min(820px, calc(100vh - 76px));
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(360px, 0.72fr);
  align-items: center;
  gap: clamp(26px, 5vw, 68px);
  padding: clamp(40px, 7vw, 92px) clamp(20px, 5vw, 64px) clamp(28px, 5vw, 58px);
}

.public-hero h1 {
  max-width: 880px;
  margin: 12px 0 18px;
  font-size: clamp(46px, 6.1vw, 84px);
  line-height: 0.98;
  letter-spacing: 0;
}

.public-hero p,
.public-auth-section p {
  max-width: 700px;
  color: #adbbb6;
  font-size: 18px;
  line-height: 1.62;
}

.public-portal-rail {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  max-width: 760px;
  margin-top: 20px;
}

.public-session-handoff {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  max-width: 760px;
  margin-top: 18px;
  padding: 12px;
  border: 1px solid rgba(82, 214, 196, 0.24);
  border-radius: var(--radius);
  background:
    linear-gradient(135deg, rgba(82, 214, 196, 0.09), rgba(255, 255, 255, 0.02)),
    rgba(8, 13, 15, 0.74);
  box-shadow: var(--shadow-tight);
}

.public-session-handoff > div:first-child {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.public-session-handoff strong,
.public-session-handoff small {
  display: block;
  min-width: 0;
}

.public-session-handoff strong {
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 15px;
}

.public-session-handoff small {
  color: var(--muted);
}

.public-server-sync-receipt {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 0.42fr);
  align-items: stretch;
  gap: 10px;
  max-width: 760px;
  margin-top: 18px;
  padding: 12px;
  overflow: hidden;
  border: 1px solid rgba(95, 240, 201, 0.18);
  border-radius: var(--radius);
  background: rgba(8, 13, 15, 0.72);
  box-shadow: var(--shadow-tight);
}

.public-server-sync-receipt > div:first-child {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.public-server-sync-receipt strong,
.public-server-sync-receipt small,
.public-server-sync-receipt span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.public-server-sync-receipt > div:first-child > strong {
  font-size: 18px;
  line-height: 1.2;
}

.public-server-sync-receipt small {
  color: var(--muted);
  line-height: 1.45;
}

.public-server-sync-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.public-server-sync-grid span {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 10px;
  border: 1px solid rgba(201, 214, 207, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.035);
}

.public-server-sync-grid strong {
  color: var(--text);
  font-size: 13px;
}

.public-server-update-receipt {
  display: grid;
  grid-column: 1 / -1;
  gap: 6px;
  min-width: 0;
  padding: 10px;
  overflow: hidden;
  border: 1px solid rgba(255, 205, 118, 0.2);
  border-radius: 8px;
  background: rgba(255, 205, 118, 0.055);
}

.public-server-update-receipt span {
  color: #ffd58a;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.public-server-update-receipt code {
  display: block;
  min-width: 0;
  padding: 8px;
  overflow-wrap: anywhere;
  border: 1px solid rgba(201, 214, 207, 0.11);
  border-radius: 7px;
  color: #f5fbf7;
  background: rgba(0, 0, 0, 0.22);
}

.public-saved-build-verification {
  display: grid;
  grid-column: 1 / -1;
  gap: 10px;
  min-width: 0;
  padding: 10px;
  overflow: hidden;
  border: 1px solid rgba(134, 174, 246, 0.2);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(134, 174, 246, 0.075), transparent 66%),
    rgba(255, 255, 255, 0.026);
}

.public-saved-build-verification > div:first-child {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.public-saved-build-verification span,
.public-saved-build-verification strong,
.public-saved-build-verification small {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.public-saved-build-verification > div:first-child > span,
.public-saved-build-grid span {
  color: #a7c2ff;
  font-size: 11px;
  font-weight: 950;
  text-transform: uppercase;
}

.public-saved-build-verification > div:first-child > strong {
  color: var(--text);
  font-size: 15px;
  line-height: 1.2;
}

.public-saved-build-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}

.public-saved-build-grid article {
  display: grid;
  gap: 5px;
  min-width: 0;
  min-height: 104px;
  padding: 10px;
  border: 1px solid rgba(201, 214, 207, 0.105);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.14);
}

.public-saved-build-grid strong {
  color: var(--text);
  font-size: 13px;
  line-height: 1.15;
}

.public-hosted-build-source-contract {
  display: grid;
  grid-column: 1 / -1;
  gap: 10px;
  min-width: 0;
  padding: 10px;
  overflow: hidden;
  border: 1px solid rgba(95, 240, 201, 0.2);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(95, 240, 201, 0.065), rgba(134, 174, 246, 0.04)),
    rgba(255, 255, 255, 0.026);
}

.public-hosted-build-source-contract > div:first-child {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.public-hosted-build-source-contract span,
.public-hosted-build-source-contract strong,
.public-hosted-build-source-contract small {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.public-hosted-build-source-contract > div:first-child > span,
.public-hosted-build-source-grid span {
  color: #77f6dc;
  font-size: 11px;
  font-weight: 950;
  text-transform: uppercase;
}

.public-hosted-build-source-contract > div:first-child > strong {
  color: var(--text);
  font-size: 15px;
  line-height: 1.2;
}

.public-hosted-build-source-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}

.public-hosted-build-source-grid article {
  display: grid;
  gap: 5px;
  min-width: 0;
  min-height: 104px;
  padding: 10px;
  border: 1px solid rgba(201, 214, 207, 0.105);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.14);
}

.public-hosted-build-source-grid strong {
  color: var(--text);
  font-size: 13px;
  line-height: 1.15;
}

.public-hosted-build-source-contract button {
  justify-self: start;
}

.public-session-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.public-session-actions button {
  min-height: 38px;
}

.public-portal-rail button {
  min-height: 106px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px;
  text-align: left;
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.02)),
    rgba(8, 13, 15, 0.66);
  box-shadow: var(--shadow-tight);
  transition:
    border-color 160ms ease,
    background 160ms ease,
    transform 160ms ease;
}

.public-portal-rail button:hover {
  transform: translateY(-1px);
  border-color: var(--line-strong);
}

.public-portal-rail button.active {
  border-color: rgba(82, 214, 196, 0.52);
  background:
    linear-gradient(135deg, rgba(82, 214, 196, 0.14), rgba(255, 255, 255, 0.028)),
    rgba(8, 13, 15, 0.76);
  box-shadow: 0 16px 38px rgba(82, 214, 196, 0.1);
}

.public-portal-rail strong,
.public-portal-rail small,
.auth-card-heading strong,
.auth-card-heading small {
  display: block;
}

.public-portal-rail small {
  margin-top: 6px;
}

.portal-launch-map {
  display: grid;
  gap: 12px;
  max-width: 760px;
  margin-top: 16px;
  padding: 12px;
  border: 1px solid rgba(82, 214, 196, 0.2);
  border-radius: var(--radius);
  background:
    linear-gradient(135deg, rgba(82, 214, 196, 0.075), rgba(134, 174, 246, 0.04)),
    rgba(8, 13, 15, 0.72);
  box-shadow: var(--shadow-tight);
}

.portal-launch-map > div:first-child {
  display: grid;
  gap: 7px;
}

.portal-launch-map strong,
.portal-launch-map small,
.portal-launch-map span {
  display: block;
  min-width: 0;
}

.portal-launch-map > div:first-child > strong {
  font-size: 16px;
  line-height: 1.2;
}

.portal-launch-map-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.portal-launch-map-grid button {
  display: grid;
  gap: 6px;
  min-height: 156px;
  padding: 11px;
  text-align: left;
  color: var(--text);
  border: 1px solid rgba(255, 255, 255, 0.085);
  border-radius: var(--radius);
  background: rgba(0, 0, 0, 0.14);
}

.portal-launch-map-grid button.active {
  border-color: rgba(82, 214, 196, 0.48);
  background:
    linear-gradient(135deg, rgba(82, 214, 196, 0.14), rgba(134, 174, 246, 0.045)),
    rgba(255, 255, 255, 0.035);
}

.portal-launch-map-grid span {
  color: var(--teal);
  font-size: 11px;
  font-weight: 950;
  text-transform: uppercase;
}

.portal-launch-map-grid strong {
  font-size: 16px;
  line-height: 1.15;
}

.portal-launch-map-grid small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.public-buyer-decision-board {
  display: grid;
  gap: 12px;
  max-width: 960px;
  margin-top: 16px;
  padding: 14px;
  overflow: hidden;
  border: 1px solid rgba(95, 240, 201, 0.22);
  border-radius: var(--radius);
  background:
    linear-gradient(135deg, rgba(95, 240, 201, 0.085), rgba(225, 184, 102, 0.05)),
    rgba(8, 13, 15, 0.76);
  box-shadow: var(--shadow-tight);
}

.public-buyer-decision-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(160px, auto);
  gap: 12px;
  align-items: stretch;
}

.public-buyer-decision-header > div:first-child {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.public-buyer-decision-board strong,
.public-buyer-decision-board small,
.public-buyer-decision-board span,
.public-buyer-decision-board b {
  min-width: 0;
  overflow-wrap: anywhere;
}

.public-buyer-decision-header strong {
  color: var(--text);
  font-size: 18px;
  line-height: 1.15;
}

.public-buyer-decision-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.public-buyer-decision-grid article {
  display: grid;
  align-content: start;
  gap: 9px;
  min-width: 0;
  min-height: 292px;
  padding: 12px;
  border: 1px solid rgba(201, 214, 207, 0.12);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.035);
}

.public-buyer-decision-grid article.active {
  border-color: rgba(95, 240, 201, 0.48);
  background:
    linear-gradient(135deg, rgba(95, 240, 201, 0.12), rgba(134, 174, 246, 0.045)),
    rgba(255, 255, 255, 0.035);
}

.public-buyer-decision-grid article > span {
  color: #65f0d0;
  font-size: 12px;
  font-weight: 950;
  text-transform: uppercase;
}

.public-buyer-decision-grid article > strong {
  color: var(--text);
  font-size: 18px;
  line-height: 1.12;
}

.public-buyer-decision-grid article > div {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 9px;
  border: 1px solid rgba(201, 214, 207, 0.1);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.16);
}

.public-buyer-decision-grid b {
  color: rgba(237, 245, 240, 0.92);
  font-size: 11px;
  text-transform: uppercase;
}

.public-buyer-decision-grid small,
.public-buyer-decision-proof small,
.public-buyer-decision-header small {
  color: var(--muted);
  line-height: 1.36;
}

.public-buyer-decision-grid button {
  align-self: end;
  width: 100%;
}

.public-buyer-decision-proof {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 10px;
  border: 1px solid rgba(201, 214, 207, 0.11);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.14);
}

.public-buyer-decision-proof span {
  color: #b7f9e9;
  font-size: 12px;
  font-weight: 900;
}

.public-proof {
  display: grid;
  gap: 12px;
}

.public-command-center {
  position: relative;
  padding: 14px;
  border: 1px solid rgba(201, 214, 207, 0.16);
  border-radius: var(--radius);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.026)),
    rgba(8, 13, 15, 0.72);
  box-shadow: 0 32px 110px rgba(0, 0, 0, 0.48);
}

.command-center-top,
.command-center-record,
.command-center-microgrid section,
.command-center-footer {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.035);
}

.command-center-top {
  display: grid;
  gap: 8px;
  padding: 16px;
  border-color: rgba(82, 214, 196, 0.22);
  background:
    linear-gradient(135deg, rgba(82, 214, 196, 0.11), rgba(134, 174, 246, 0.055)),
    rgba(255, 255, 255, 0.035);
}

.command-center-top strong {
  font-size: 22px;
  line-height: 1.1;
}

.command-center-record {
  display: grid;
  gap: 6px;
  padding: 14px;
}

.command-center-record span {
  color: var(--teal);
  font-size: 11px;
  font-weight: 950;
  text-transform: uppercase;
}

.command-center-record strong {
  font-size: 18px;
}

.command-center-record small,
.command-center-top small {
  line-height: 1.4;
}

.command-center-microgrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.command-center-microgrid section {
  display: grid;
  gap: 8px;
  min-height: 116px;
  padding: 14px;
}

.command-center-microgrid strong {
  color: var(--teal);
  font-size: 34px;
  line-height: 1;
}

.trust-network-visual {
  position: relative;
  min-height: 268px;
  overflow: hidden;
  border: 1px solid rgba(201, 214, 207, 0.14);
  border-radius: var(--radius);
  background:
    linear-gradient(90deg, rgba(201, 214, 207, 0.045) 1px, transparent 1px),
    linear-gradient(180deg, rgba(201, 214, 207, 0.045) 1px, transparent 1px),
    linear-gradient(135deg, rgba(82, 214, 196, 0.09), rgba(134, 174, 246, 0.055) 56%, rgba(225, 184, 102, 0.06)),
    rgba(255, 255, 255, 0.026);
  background-size: 34px 34px, 34px 34px, auto, auto;
}

.trust-network-visual::before,
.trust-network-visual::after {
  content: "";
  position: absolute;
  inset: 50% 12% auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(82, 214, 196, 0.72), rgba(134, 174, 246, 0.42), transparent);
}

.trust-network-visual::after {
  inset: 18% 50% 14%;
  width: 1px;
  height: auto;
  background: linear-gradient(180deg, transparent, rgba(225, 184, 102, 0.5), rgba(82, 214, 196, 0.58), transparent);
}

.trust-network-node {
  position: absolute;
  z-index: 1;
  display: grid;
  gap: 4px;
  width: clamp(118px, 32%, 148px);
  min-height: 70px;
  align-content: center;
  padding: 10px;
  border: 1px solid rgba(201, 214, 207, 0.18);
  border-radius: var(--radius);
  background: rgba(8, 13, 15, 0.78);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.28);
}

.trust-network-node span {
  display: block;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--muted);
  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0;
  line-height: 1;
  text-transform: uppercase;
}

.trust-network-node strong {
  display: block;
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  font-size: 16px;
  line-height: 1.05;
}

.trust-network-node.primary {
  top: 18px;
  left: 50%;
  border-color: rgba(82, 214, 196, 0.48);
  transform: translateX(-50%);
}

.trust-network-node.evidence {
  top: 108px;
  left: 18px;
  border-color: rgba(134, 174, 246, 0.38);
}

.trust-network-node.consent {
  right: 50%;
  bottom: 18px;
  border-color: rgba(225, 184, 102, 0.4);
  transform: translateX(50%);
}

.trust-network-node.verify {
  right: 18px;
  top: 108px;
  border-color: rgba(112, 224, 178, 0.38);
}

.command-center-footer {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 10px;
}

.command-center-footer span {
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  padding: 0 9px;
  color: var(--muted);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.03);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.public-proof:not(.public-command-center) div,
.portal-grid article,
.portal-route-grid article,
.pricing-card,
.public-auth-card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--panel);
  box-shadow: var(--shadow);
}

.public-proof:not(.public-command-center) div {
  min-height: 126px;
  display: grid;
  align-content: center;
  gap: 8px;
  padding: 20px;
  background:
    linear-gradient(140deg, rgba(255, 255, 255, 0.065), rgba(255, 255, 255, 0.018)),
    rgba(17, 27, 31, 0.86);
}

.public-proof span,
.pricing-card span {
  color: var(--teal);
  font-size: 38px;
  line-height: 1;
  font-weight: 950;
}

.public-command-center > span {
  font-size: 12px;
}

.public-section,
.public-auth-section {
  padding: clamp(38px, 6vw, 76px) clamp(20px, 5vw, 64px);
  border-top: 1px solid var(--line);
}

.public-section-heading {
  margin-bottom: 18px;
}

.public-section-heading h2,
.public-auth-section h2 {
  margin: 8px 0 0;
  font-size: clamp(30px, 4vw, 48px);
  line-height: 1;
}

