/* VPS workspace layout guard: final cascade layer for the hosted SaaS workspace. */
html,
body {
  max-width: 100%;
  overflow-x: hidden;
}

.app,
.workspace,
.topbar,
.hero,
.metrics-grid,
.workspace-command-strip,
.workspace-admin-grid,
.work-grid,
.records-panel,
.detail-panel,
.actions-panel,
.verify-panel,
.setup-panel-grid,
.setup-tabs,
.records-list {
  min-width: 0;
  max-width: 100%;
  overflow-x: clip;
}

.workspace {
